func (s *State) reaction(v ReactionModel) Reaction{return Reaction{ID:v.ID,User:s.user(v.UserID),Livestream:s.stream(v.LivestreamID),EmojiName:v.EmojiName,CreatedAt:v.CreatedAt}}
